using System.Collections.Generic;
using System.Text.Json.Serialization;
using Adyen.Core.Models;

namespace Adyen.Models;

public record NonprofitCause
{
    /// <summary>
    /// The URL to the banner of the cause.
    /// </summary>
    [JsonPropertyName("bannerUrl")]
    public required string BannerUrl { get; init; }

    /// <summary>
    /// The description of the cause.
    /// </summary>
    [JsonPropertyName("description")]
    public required string Description { get; init; }

    /// <summary>
    /// The unique identifier of the cause. This value is generated by Adyen.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("id")]
    public string? Id { get; init; }

    /// <summary>
    /// The locales that the cause supports, in <see href="https://en.wikipedia.org/wiki/IETF_language_tag">IETF BCP 47</see> format.
    /// </summary>
    [JsonPropertyName("locales")]
    public required IReadOnlyList<string> Locales { get; init; }

    /// <summary>
    /// The name of the cause.
    /// </summary>
    [JsonPropertyName("name")]
    public required string Name { get; init; }

    [JsonExtensionData]
    public AdditionalProperties AdditionalProperties { get; init; } = [];
}
